// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp) public {
        // Bound the fuzzed timestamp to a reasonable range
        timestamp = bound(timestamp, 1, type(uint40).max);

        // Set the block timestamp
        vm.warp(timestamp);

        // Fund this contract with enough ether to send 10 ether
        vm.deal(address(this), 10 ether);

        // Call the fallback function
        (bool success,) = address(c).call{value: 10 ether}("");

        // General rule: after a successful fallback call, pastBlockTime equals the block timestamp
        if (success) {
            assertTrue(c.pastBlockTime() == timestamp);
        }
    }
}

